import os,json,subprocess,hashlib
from pathlib import Path
proj=Path('/srv/projects')
names=sorted(x.name for x in proj.iterdir() if x.is_dir() and not x.is_symlink())
units=('ssh','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads')
def cmd(a,t=8):
 try:
  r=subprocess.run(a,text=True,capture_output=True,timeout=t)
  return {'rc':r.returncode,'out':r.stdout.strip()[:320]}
 except Exception as e:return {'rc':99,'out':type(e).__name__}
def typ(path):
 p=Path(path)
 if p.is_symlink():return 'link'
 if p.is_file():return 'file'
 if p.is_dir():return 'dir'
 return 'absent'
r={'roots':names,'services':{},'outside_aliases':{},'app_specific_environment_files':{},'vault':{},'lowcost_code':{},'legacy_rea':{},'fadego_helper':{},'git':{}}
for u in units:r['services'][u]=cmd(['systemctl','is-active',u])['out']
for n in ('/etc/lowcost-europa','/var/backups/lowcost-europa','/var/lib/lowcost-europa','/srv/pink-iptv','/opt/hopper','/home/ubuntu/.cache/rea/hopper-releases'):
 r['outside_aliases'][n]=typ(n)
for name,service in [('FADEGO','fadego-staging'),('PINK','pink-iptv-backend'),('LOWCOST','lowcost-europa')]:
 v=cmd(['systemctl','cat',service],10)['out']
 r['app_specific_environment_files'][name]=[x.strip() for x in v.splitlines() if x.strip().startswith('EnvironmentFile=')][:8]
for p in ('/root/project-secrets','/root/project-secrets/lowcost-europa'):
 v=Path(p)
 r['vault'][p]={'kind':typ(p),'mode':oct(v.stat().st_mode&0o777) if v.exists() else None,'target':str(v.resolve(strict=False)) if v.is_symlink() else None}
r['vault']['backup_timer']=cmd(['systemctl','is-active','project-secrets-offsite-backup.timer'])['out']
r['vault']['backup_exec']=[x.strip() for x in cmd(['systemctl','cat','project-secrets-offsite-backup.service'])['out'].splitlines() if x.strip().startswith('ExecStart=')]
r['legacy_rea']['final']=typ('/srv/projects/Engenheira-reversa')
r['legacy_rea']['trial']=typ('/srv/projects/REA-Trial')
r['legacy_rea']['hopper_apt']=cmd(['dpkg-query','-W','hopper'])['rc']
for n in ('/usr/local/sbin/fadego-password','/srv/projects/fadego/tools/fadego-password'):
 p=Path(n)
 r['fadego_helper'][n]={'kind':typ(n),'sha256':hashlib.sha256(p.read_bytes()).hexdigest() if p.is_file() and p.stat().st_size<20000 else None}
q=Path('/srv/projects/lowcost-europa')
for n in ('offsite-backup.sh','offsite-restore-drill.sh','backup-postgres.sh','check-offsite-backup-health.sh'):
 p=q/'deploy/scripts'/n
 if p.is_file():
  s=p.read_text(errors='replace')
  z=cmd(['/bin/sh','-n',str(p)])
  r['lowcost_code'][n]={'syntax_pass':z['rc']==0,'uses_live_external_etc':any('/etc/lowcost-europa/' in l and '$target' not in l for l in s.splitlines()),'uses_canonical_private':'/srv/projects/lowcost-europa/private/systemd-env/' in s,'legacy_archive_read_only':n=='offsite-restore-drill.sh' and '$target/etc/lowcost-europa/' in s}
r['git']['lowcost_local_changes']=len(cmd(['git','-c','safe.directory=/srv/projects/lowcost-europa','-C',str(q),'status','--porcelain','--untracked-files=no'],12)['out'].splitlines())
r['git']['lowcost_HEAD']=cmd(['git','-c','safe.directory=/srv/projects/lowcost-europa','-C',str(q),'rev-parse','HEAD'])['out']
r['ferrari_current']=str((proj/'skill-universal/current').resolve(strict=False))
fs=os.statvfs('/')
r['disk_free_gib']=round(fs.f_bavail*fs.f_frsize/1024**3,2)
print(json.dumps(r,separators=(',',':')))
